fn solve(nums: Vec<i8>) -> Vec<char> {
    // We expect exactly three integers.
    let mut v = nums;
    v.sort(); // sort in nondecreasing order

    let (a, b, c) = (v[0], v[1], v[2]);

    let is_yes = 
        // at least one of them is 1
        a == 1
        // at least two of them are 2
        || (a == 2 && b == 2)
        // exactly the triple (2, 4, 4)
        || (a == 2 && b == 4 && c == 4)
        // exactly the triple (3, 3, 3)
        || (a == 3 && b == 3 && c == 3);

    if is_yes {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

